import dlt
from pyspark.sql import functions as F
from pyspark.sql.window import Window

@dlt.table(name="silver_orders", comment="Cleaned, deduplicated orders")
@dlt.expect_or_drop("valid_amount", "amount > 0")
@dlt.expect_or_drop("has_id", "order_id IS NOT NULL")
def silver_orders():
    w = Window.partitionBy("order_id").orderBy(F.col("updated_at").desc())
    return (dlt.read_stream("bronze_orders")
            .withColumn("amount", F.col("amount").cast("double"))
            .withColumn("rn", F.row_number().over(w))
            .filter(F.col("rn") == 1)
            .drop("rn"))

@dlt.table(name="gold_daily_revenue", comment="Daily revenue by region")
def gold_daily_revenue():
    return (dlt.read("silver_orders")
            .groupBy(F.to_date("order_ts").alias("order_date"), "region")
            .agg(F.sum("amount").alias("revenue"),
                 F.countDistinct("order_id").alias("orders")))

-- Liquid clustering on common filter/join keys
ALTER TABLE prod.gold.daily_revenue CLUSTER BY (order_date, region);

-- Compact files and apply clustering
OPTIMIZE prod.gold.daily_revenue;

-- Unity Catalog governance: grant read to analysts
GRANT USE CATALOG ON CATALOG prod TO `finance_analysts`;
GRANT USE SCHEMA ON SCHEMA prod.gold TO `finance_analysts`;
GRANT SELECT ON TABLE prod.gold.daily_revenue TO `finance_analysts`;

-- Column mask for PII in silver (only admins see raw email)
CREATE FUNCTION prod.silver.mask_email(email STRING)
RETURN CASE WHEN is_account_group_member('admins') THEN email
            ELSE '***@masked' END;
ALTER TABLE prod.silver.customers
  ALTER COLUMN email SET MASK prod.silver.mask_email;
